# BillKora - MikroTik Check & Live Status installer
# Run:  powershell -ExecutionPolicy Bypass -File C:\billkora\Install-MikroTik-Check.ps1
$ErrorActionPreference = 'Stop'
$root = 'C:\billkora'
function Step($m) { Write-Host "`n==> $m" -ForegroundColor Cyan }
if (-not (Test-Path "$root\server.js")) { throw 'C:\billkora\server.js not found.' }
$utf8 = New-Object Text.UTF8Encoding $false
$bk = Join-Path $root ('backup-mtcheck-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))

Step 'Stopping BillKora'
Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -ne $PID -and $_.CommandLine -like '*billkora*' -and $_.Name -in 'node.exe','powershell.exe','msedge.exe' } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }

Step "Backing up files to $bk"
New-Item -ItemType Directory "$bk\public" -Force | Out-Null
foreach ($f in 'server.js','public\admin.html','public\erp.js','public\migration.js') { Copy-Item "$root\$f" "$bk\$f" -Force }

function Patch($file, $find, $repl, $marker) {
    $p = Join-Path $root $file
    $t = [IO.File]::ReadAllText($p)
    if ($t.Contains($marker)) { Write-Host "  already patched: $file"; return }
    if (-not $t.Contains($find)) { throw "Could not find the place to patch in $file" }
    $i = $t.IndexOf($find)
    $t = $t.Substring(0, $i) + $repl + $t.Substring($i + $find.Length)
    [IO.File]::WriteAllText($p, $t, $utf8)
    Write-Host "  patched: $file"
}
function Restore { foreach ($f in 'server.js','public\admin.html','public\erp.js','public\migration.js') { Copy-Item "$bk\$f" "$root\$f" -Force }; Write-Host 'Rolled back to your old files.' -ForegroundColor Yellow }

try {
