Step 'Checking the code'
$node = Join-Path $root 'runtime\node.exe'
if (-not (Test-Path $node)) { $c = Get-Command node -ErrorAction SilentlyContinue; if ($c) { $node = $c.Source } else { $node = "$env:ProgramFiles\nodejs\node.exe" } }
$ErrorActionPreference = 'Continue'
foreach ($f in 'server.js','mt.js','mtcheck.js','public\mtcheck.js','public\migration.js','public\erp.js') {
    $out = & $node --check "$root\$f" 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Syntax check failed for $f : $out" }
    Write-Host "  ok: $f"
}
$ErrorActionPreference = 'Stop'
